const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
export const ROBOT_MAX_SPEED=500/3.6;
export function transformRobot(s){if(!s.flight||!s.airborne||s.shotDown||s.onFoot||s.boat)return false;s.robot=!s.robot;s.landing=false;s.stall=false;s.pitchRate=s.rollRate=s.flightBank=0;if(s.robot){const v=Math.min(ROBOT_MAX_SPEED,Math.abs(s.speed));s.robotVx=-Math.sin(s.yaw)*v;s.robotVz=-Math.cos(s.yaw)*v;s.robotVy=clamp(s.verticalSpeed||0,-ROBOT_MAX_SPEED,ROBOT_MAX_SPEED);s.flightPitch=0;s.flightThrottle=0;}else{const forward=-(s.robotVx||0)*Math.sin(s.yaw)-(s.robotVz||0)*Math.cos(s.yaw);s.speed=Math.max(32,forward);s.verticalSpeed=s.robotVy||0;s.flightPitch=Math.atan2(s.verticalSpeed,s.speed);s.flightThrottle=.85;s.robotVx=s.robotVy=s.robotVz=0;}return true;}
export function stepRobot(s,dt,input={},floor=0){if(!s.robot||s.shotDown||dt<=0)return;dt=Math.min(dt,1/30);s.yaw-=(input.rudder||0)*2.1*dt;const mx=input.moveX||0,my=input.moveY||0,mz=input.lift||0,n=Math.max(1,Math.hypot(mx,my,mz)),v=ROBOT_MAX_SPEED*(1-.85*(s.brake||0)),vx=(Math.cos(s.yaw)*mx-Math.sin(s.yaw)*my)/n*v,vz=(-Math.sin(s.yaw)*mx-Math.cos(s.yaw)*my)/n*v,vy=mz/n*v,k=1-Math.exp(-3.5*dt);s.robotVx=((s.robotVx||0)+(vx-(s.robotVx||0))*k);s.robotVz=((s.robotVz||0)+(vz-(s.robotVz||0))*k);s.robotVy=((s.robotVy||0)+(vy-(s.robotVy||0))*k);const total=Math.hypot(s.robotVx,s.robotVy,s.robotVz);if(total>ROBOT_MAX_SPEED){const scale=ROBOT_MAX_SPEED/total;s.robotVx*=scale;s.robotVy*=scale;s.robotVz*=scale;}s.x+=s.robotVx*dt;s.z+=s.robotVz*dt;s.y+=s.robotVy*dt;if(s.y<floor+2){s.y=floor+2;s.robotVy=Math.max(0,s.robotVy);}s.speed=Math.hypot(s.robotVx,s.robotVz);s.verticalSpeed=s.robotVy;s.flightPitch=clamp(input.pitch||0,-1.25,1.25);s.flightBank=0;s.distance+=Math.hypot(s.speed,s.verticalSpeed)*dt;s.rpm=1200+Math.hypot(s.speed,s.verticalSpeed)*20;s.airborne=true;s.stall=false;}
